// --- CONFIGURATION ---
const source = "Wicks";      // "Wicks" or "Bodys"
const leftLen = 100;         // Left Bars (Strength lookback)
const rightLen = 3;          // Right Bars (Confirmation delay)

const n = candles.length;
if (!candles || n < leftLen + rightLen + 1) return [];

const points = [];
const bullBoxes = [];
const bearBoxes = [];

for (let i = leftLen + rightLen; i < n; i++) {
  const k = i - rightLen; // The candidate pivot candle index
  const currCandle = candles[i];
  const currClose = currCandle.close;

  // 1. Pivot High Check
  let isPivotHigh = true;
  const phVal_k = source === "Wicks" ? candles[k].high : candles[k].close;

  for (let offset = 1; offset <= leftLen; offset++) {
    const val = source === "Wicks" ? candles[k - offset].high : candles[k - offset].close;
    if (val >= phVal_k) { isPivotHigh = false; break; }
  }
  if (isPivotHigh) {
    for (let offset = 1; offset <= rightLen; offset++) {
      const val = source === "Wicks" ? candles[k + offset].high : candles[k + offset].close;
      if (val > phVal_k) { isPivotHigh = false; break; }
    }
  }

  if (isPivotHigh) {
    bearBoxes.push({
      top: candles[k].high,
      bottom: Math.min(candles[k].open, candles[k].close),
      active: true
    });
  }

  // 2. Pivot Low Check
  let isPivotLow = true;
  const plVal_k = source === "Wicks" ? candles[k].low : candles[k].close;

  for (let offset = 1; offset <= leftLen; offset++) {
    const val = source === "Wicks" ? candles[k - offset].low : candles[k - offset].close;
    if (val <= plVal_k) { isPivotLow = false; break; }
  }
  if (isPivotLow) {
    for (let offset = 1; offset <= rightLen; offset++) {
      const val = source === "Wicks" ? candles[k + offset].low : candles[k + offset].close;
      if (val < plVal_k) { isPivotLow = false; break; }
    }
  }

  if (isPivotLow) {
    bullBoxes.push({
      top: Math.max(candles[k].open, candles[k].close),
      bottom: candles[k].low,
      active: true
    });
  }

  // 3. Invalidation Check
  // Bullish zone invalid when close < box bottom
  for (let b = bullBoxes.length - 1; b >= 0; b--) {
    if (bullBoxes[b].active && currClose < bullBoxes[b].bottom) {
      bullBoxes[b].active = false;
    }
  }

  // Bearish zone invalid when close > box top
  for (let b = bearBoxes.length - 1; b >= 0; b--) {
    if (bearBoxes[b].active && currClose > bearBoxes[b].top) {
      bearBoxes[b].active = false;
    }
  }

  // Determine active level to plot on the chart
  const activeBull = bullBoxes.slice().reverse().find(b => b.active);
  const activeBear = bearBoxes.slice().reverse().find(b => b.active);

  let plotVal = currClose;
  if (activeBull && activeBear) {
    plotVal = Number(((activeBull.top + activeBear.bottom) / 2).toFixed(3));
  } else if (activeBull) {
    plotVal = Number(activeBull.top.toFixed(3));
  } else if (activeBear) {
    plotVal = Number(activeBear.bottom.toFixed(3));
  }

  points.push({
    time: currCandle.time,
    value: plotVal
  });
}

// Return the required [{ time, value }] array
return points;
